use std::{collections::{HashMap,HashSet},env,fs};
#[derive(Clone)]struct I{paper:String,ex:String,fa:String,fam:String,th:String,edges:HashSet<String>,cont:HashSet<String>,authors:HashSet<String>,title:HashSet<String>,methods:HashSet<String>}
fn pair(a:&str,b:&str)->String{if a<b{format!("{}\n{}",a,b)}else{format!("{}\n{}",b,a)}}
fn chain(es:&HashSet<String>)->bool{let mut n:HashMap<&str,HashSet<&str>>=HashMap::new();for e in es{let mut p=e.splitn(2,'>');let a=p.next().unwrap_or("");let b=p.next().unwrap_or("");n.entry(a).or_default().insert(b);}for e in es{let mut p=e.splitn(2,'>');let _=p.next();let b=p.next().unwrap_or("");if n.get(b).map(|x|!x.is_empty()).unwrap_or(false){return true}}false}
fn jac(a:&HashSet<String>,b:&HashSet<String>)->f64{let i=a.intersection(b).count();let u=a.len()+b.len()-i;if u==0{0.0}else{i as f64/u as f64}}
fn indep(a:&I,b:&I)->bool{if a.authors.is_empty()||b.authors.is_empty(){return false}if a.authors.intersection(&b.authors).next().is_some(){return false}let m=a.methods.intersection(&b.methods).next().is_some();if m&&jac(&a.title,&b.title)>=0.15{return false}true}
fn count(items:&HashMap<String,I>,family:bool)->(usize,HashSet<String>,HashSet<String>,HashSet<String>){let mut post:HashMap<String,Vec<String>>=HashMap::new();for(id,x)in items{let c=if family{&x.fa}else{&x.ex};for e in &x.edges{post.entry(format!("{}|{}",c,e)).or_default().push(id.clone());}}let mut ps:HashMap<String,(String,String,HashSet<String>)>=HashMap::new();for(k,xs)in post{let e=k.split_once('|').map(|x|x.1).unwrap_or("").to_string();let u:Vec<String>=xs.into_iter().collect::<HashSet<_>>().into_iter().collect();for i in 0..u.len(){for j in i+1..u.len(){let pk=pair(&u[i],&u[j]);ps.entry(pk).or_insert((u[i].clone(),u[j].clone(),HashSet::new())).2.insert(e.clone());}}}let mut n=0;let mut papers=HashSet::new();let mut fams=HashSet::new();let mut comps=HashSet::new();for(_, (a,b,sh))in ps{let x=&items[&a];let y=&items[&b];if x.paper==y.paper||x.th==y.th||sh.len()<2||!chain(&sh){continue}if x.cont.difference(&y.cont).next().is_none()||y.cont.difference(&x.cont).next().is_none(){continue}if !indep(x,y){continue}n+=1;papers.insert(x.paper.clone());papers.insert(y.paper.clone());if family{fams.insert(x.fam.clone());}comps.insert(x.authors.iter().cloned().collect::<Vec<_>>().join(";"));comps.insert(y.authors.iter().cloned().collect::<Vec<_>>().join(";"));}(n,papers,fams,comps)}
fn set(s:&str)->HashSet<String>{s.split(';').filter(|x|!x.is_empty()).map(str::to_string).collect()}
fn main(){let a:Vec<String>=env::args().collect();let s=fs::read_to_string(&a[1]).unwrap();let mut m=HashMap::new();for l in s.lines(){if l.trim().is_empty(){continue}let p:Vec<&str>=l.split('\t').collect();if p.len()!=11{panic!("bad {}",p.len())}m.insert(p[0].to_string(),I{paper:p[1].into(),ex:p[2].into(),fa:p[3].into(),fam:p[4].into(),th:p[5].into(),edges:set(p[6]),cont:set(p[7]),authors:set(p[8]),title:set(p[9]),methods:set(p[10])});}let(e,_,_,_)=count(&m,false);let(f,p,fa,c)=count(&m,true);println!("exact_independent\t{}",e);println!("family_independent\t{}",f);println!("family_distinct_papers\t{}",p.len());println!("family_distinct_families\t{}",fa.len());println!("family_author_components\t{}",c.len());}
